                startCode: "// Why not a table? A Q table needs a row for every situation it can be in. Predict first: how many different\n// six-card hands are there, before even counting whose crib it is or what has been played?\nconst choose = (n, k) => { let r = 1; for (let i = 0; i < k; i++) r = r * (n - i) / (i + 1); return r }\nconsole.log('six-card hands: ' + choose(52, 6).toLocaleString('en'))\nconsole.log('× 2 (whose crib) × 15 throws: ' + (choose(52, 6) * 2 * 15).toLocaleString('en') + ' throw values to learn')\nconsole.log('8,000 training hands visit at most 1 in ' + Math.round(choose(52, 6) * 2 / 8000).toLocaleString('en') + ' of the ' + (choose(52, 6) * 2).toLocaleString('en') + ' hand-and-crib situations, each about once')\nconsole.log('So: describe a move by a few numbers that mean the same thing in every hand, and learn a weight for each.')",
